func isSmith(n) = {
  local pSum = 0
  local temp = n
  local factors = 0
  for (i: 2 .. floor(sqrt(n))) {
    while (temp % i == 0) {
      pSum = pSum + sumDigits(i)
      temp = temp / i
      factors = factors + 1
    }
  }
  if (temp > 1) {
    pSum = pSum + sumDigits(temp)
    factors = factors + 1
  }
  factors > 1 && sumDigits(n) == pSum
}
